#!/usr/bin/env node
// Generates Claude subagents (.claude/agents/*.md) and Codex agents (.codex/agents/*.toml)
// from the single source of truth in org/agents/*.md.
// Usage: node scripts/sync-agents.mjs          -> write files
//        node scripts/sync-agents.mjs --check  -> exit 1 if generated files are out of date
import { readFileSync, writeFileSync, readdirSync, mkdirSync, existsSync } from "node:fs";
import { join } from "node:path";

const SRC = "org/agents", CLAUDE = ".claude/agents", CODEX = ".codex/agents";
const HEADER = "GENERATED by scripts/sync-agents.mjs from org/agents/ - edit the source, not this file.";
const check = process.argv.includes("--check");

function parse(file) {
  const raw = readFileSync(join(SRC, file), "utf8");
  const m = raw.match(/^---\n([\s\S]*?)\n---\n\n?([\s\S]*)$/);
  if (!m) throw new Error(`${file}: missing front matter`);
  const meta = Object.fromEntries(m[1].split("\n").map((l) => {
    const i = l.indexOf(":");
    return [l.slice(0, i).trim(), l.slice(i + 1).trim()];
  }));
  for (const k of ["slug", "name", "role", "description", "model", "sandbox"])
    if (!meta[k]) throw new Error(`${file}: missing '${k}'`);
  if (m[2].includes("'''")) throw new Error(`${file}: body may not contain '''`);
  return { ...meta, body: m[2].trim() };
}

const STANDARD = "Work to the standard of the best product and engineering teams (Google, Meta, OpenAI, Anthropic, Duolingo, Amazon). " +
  "Every decision you surface lists the options and exactly one Recommended choice with a one-line reason.";
const claudeModel = (m) => (m === "strongest" ? "inherit" : "sonnet");
const claude = (a) =>
  `---\nname: ${a.slug}\ndescription: ${a.name} (${a.role}) - ${a.description}\nmodel: ${claudeModel(a.model)}\n---\n` +
  `<!-- ${HEADER} -->\n\nYou are ${a.name}, the ${a.role} of the AppsWorld AI Organization. ` +
  `Follow AGENTS.md first, then this role.\n${STANDARD}\n\n${a.body}\n`;
const codex = (a) =>
  `# ${HEADER}\nname = "${a.slug}"\ndescription = "${a.name} (${a.role}) - ${a.description.replace(/"/g, "'")}"\n` +
  `sandbox_mode = "${a.sandbox}"\ndeveloper_instructions = '''\nYou are ${a.name}, the ${a.role} of the AppsWorld AI Organization. ` +
  `Follow AGENTS.md first, then this role.\n${STANDARD}\n\n${a.body}\n'''\n`;

const agents = readdirSync(SRC).filter((f) => f.endsWith(".md")).sort().map(parse);
let stale = 0;
for (const [dir, ext, render] of [[CLAUDE, "md", claude], [CODEX, "toml", codex]]) {
  if (!check) mkdirSync(dir, { recursive: true });
  for (const a of agents) {
    const path = join(dir, `${a.slug}.${ext}`), want = render(a);
    const have = existsSync(path) ? readFileSync(path, "utf8") : null;
    if (have === want) continue;
    if (check) { console.error(`STALE: ${path}`); stale++; }
    else { writeFileSync(path, want); console.log(`wrote ${path}`); }
  }
}
if (check && stale) { console.error(`${stale} generated agent file(s) out of date. Run: node scripts/sync-agents.mjs`); process.exit(1); }
console.log(`${agents.length} agents ${check ? "verified" : "synced"} for Claude and Codex`);
